# Exact finite-grid verifier for R007/L1 (repaired).
# Only allowed import: math. No print/sys/json/filesystem/network.
# Deterministic, exact integer arithmetic, fail-closed: failure raises ValueError.
from math import isqrt

N_MAX = 3000
C_VALUES = [(1, 4), (1, 2), (3, 4), (1, 1)]

def sieve(limit):
    s = bytearray([1]) * (limit + 1)
    s[0:2] = b'\x00\x00'
    for i in range(2, isqrt(limit) + 1):
        if s[i]:
            s[i*i::i] = bytearray(len(s[i*i::i]))
    return [i for i in range(2, limit + 1) if s[i]]

PRIMES = sieve(N_MAX)
PRIME_SET = set(PRIMES)

def legendre(m, p):
    # v_p(m!) exactly
    t = 0
    while m:
        m //= p
        t += m
    return t

def v_binom(n, k, p):
    # v_p(C(n,k)) exactly, via Legendre
    return legendre(n, p) - legendre(k, p) - legendre(n - k, p)

def true_largest_prime_factor_binom(n, k):
    best = 0
    for p in PRIMES:
        if p > n:
            break
        if v_binom(n, k, p) > 0:
            if p > best:
                best = p
    return best

def bound_geq_target(x, k, a, b):
    # exact: x >= k^(1 + a/b)  <=>  x^b >= k^(b + a)
    return x ** b >= k ** (b + a)

def check_c(n, k, a, b):
    # need P(C(n,k)) >= min(n-k+1, k^(1+c)), all exact
    if k == n:
        # C=1, P(1)=1 by contract convention; min(1, n^(1+c)) = 1
        return 1 >= 1
    if k == 1:
        # C(n,1)=n; P(n) by exact trial division (n <= 3000)
        m = n
        best = 1
        d = 2
        while d * d <= m:
            while m % d == 0:
                m //= d
                if d > best:
                    best = d
            d += 1
        if m > 1 and m > best:
            best = m
        return best >= (n - 1 + 1)  # min(n, k^(1+c)) = min(n, 1) = 1... exact below
    # general k: 2 <= k <= n-1
    # determine which arm is the min, exactly
    use_nk1 = (n - k + 1) ** b <= k ** (b + a)
    if use_nk1:
        bound_int = n - k + 1
    else:
        bound_int = None  # bound = k^(1+c), compared as x^b >= k^(b+a)
    # fast path: descending primes p > k; window criterion is exact for p > k
    for p in reversed(PRIMES):
        if p > n:
            continue
        if p <= k:
            break
        # p divides C(n,k) iff a multiple of p lies in (n-k, n]
        if (n % p) < k:
            if use_nk1:
                if p >= bound_int:
                    return True
            else:
                if bound_geq_target(p, k, a, b):
                    return True
            # largest p>k divisor is below bound; but a prime <= k might still
            # be the largest prime factor -> must fall back to exact computation
            break
    # fallback: exact and complete largest prime factor of C(n,k)
    best = true_largest_prime_factor_binom(n, k)
    if use_nk1:
        return best >= bound_int
    return bound_geq_target(best, k, a, b)

def check_k1(n):
    # k=1: need P(n) >= min(n, 1^(1+c)) = min(n, 1) = 1
    return True

def verify():
    if N_MAX != 3000:
        raise ValueError("scope mismatch")
    if sorted(C_VALUES) != [(1, 1), (1, 2), (1, 4), (3, 4)]:
        raise ValueError("c_values mismatch")
    for n in range(1, N_MAX + 1):
        check_k1(n)  # k = 1
        for k in range(2, n):  # 2 <= k <= n-1
            for (a, b) in C_VALUES:
                if not check_c(n, k, a, b):
                    raise ValueError("inequality violated at n=%d k=%d c=%d/%d" % (n, k, a, b))
        # k = n handled inside check_c(k==n) semantics: P(1)=1, bound=1
        for (a, b) in C_VALUES:
            if not (1 >= 1):
                raise ValueError("k=n convention violated at n=%d" % n)
    return True
